const input = $input.first().json;

// Possible Gemini response structures
const parts =
  input?.content?.parts ??
  input?.candidates?.[0]?.content?.parts ??
  input?.response?.candidates?.[0]?.content?.parts ??
  input?.output?.content?.parts ??
  input?.parts ??
  [];

// Find the generated image
const imagePart = parts.find((part) => {
  return (
    part?.inlineData?.data ||
    part?.inline_data?.data
  );
});

if (!imagePart) {
  const textPart = parts.find((part) => part?.text);

  throw new Error(
    `Gemini did not return an image. Response: ${
      textPart?.text || JSON.stringify(input)
    }`
  );
}

const inlineData =
  imagePart.inlineData ??
  imagePart.inline_data;

const mimeType =
  inlineData.mimeType ??
  inlineData.mime_type ??
  "image/png";

const base64Data = inlineData.data;

if (!base64Data) {
  throw new Error("Gemini image data is empty.");
}

// Return an image URL that Closetly can display directly
const imageUrl = `data:${mimeType};base64,${base64Data}`;

return [
  {
    json: {
      success: true,
      imageUrl,
      mimeType,
    },
  },
];
